/* CD - Controle de Diárias | armazenamento local + Google Drive */
(() => {
  const $ = s => document.querySelector(s);
  const esc = value => String(value ?? '').replace(/[&<>\"']/g, ch => ({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',"'":'&#39;'}[ch]));
  function toast(message){const root=$('#toast-root');if(!root){console.info(message);return;}const node=document.createElement('div');node.className='toast';node.textContent=String(message);root.appendChild(node);setTimeout(()=>node.remove(),4500);}
  const money = v => Number(v||0).toLocaleString('pt-BR',{style:'currency',currency:'BRL'});
  const dateBR = v => v ? new Date(`${String(v).slice(0,10)}T12:00:00`).toLocaleDateString('pt-BR') : '—';
  const today = new Date().toISOString().slice(0,10);
  const cfg = window.APP_CONFIG || {};
  if(localStorage.getItem('CD_GOOGLE_CLIENT_ID')) cfg.GOOGLE_CLIENT_ID=localStorage.getItem('CD_GOOGLE_CLIENT_ID');
  const state = {page:'dashboard',empresas:[],diarias:[],notas:[],recebiveis:[],month:today.slice(0,7),driveBackups:[],selectedReportCompany:null};
  const tables = {empresas:'empresas',diarias:'diarias',notas:'notas_fiscais',recebiveis:'recebiveis'};
  const titles = {dashboard:'Visão geral',empresas:'Empresas',diarias:'Diárias',notas:'Notas fiscais',recebiveis:'Recebimentos',relatorios:'Relatórios',configuracoes:'Configurações e backup'};
  let localDB;
  const DB_NAME='cd-controle-diarias';
  function openLocalDB(){return new Promise((resolve,reject)=>{const req=indexedDB.open(DB_NAME,1);req.onupgradeneeded=()=>{const db=req.result;Object.values(tables).forEach(name=>{if(!db.objectStoreNames.contains(name))db.createObjectStore(name,{keyPath:'id'});});};req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error);});}
  function storeRequest(store,mode,action){return new Promise((resolve,reject)=>{const tx=localDB.transaction(store,mode),req=action(tx.objectStore(store));req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error);tx.onabort=()=>reject(tx.error);});}
  async function getAll(store){return (await storeRequest(store,'readonly',s=>s.getAll()))||[];}
  async function saveRecord(store,data,id){const record={...data,id:id||(crypto.randomUUID?crypto.randomUUID():`cd-${Date.now()}-${Math.random().toString(16).slice(2)}`),created_at:data.created_at||new Date().toISOString(),updated_at:new Date().toISOString()};await storeRequest(store,'readwrite',s=>s.put(record));return record;}
  async function deleteRecord(store,id){return storeRequest(store,'readwrite',s=>s.delete(id));}
  async function loadAll(){
    try{localDB=localDB||await openLocalDB();for(const [key,table] of Object.entries(tables))state[key]=(await getAll(table)).sort((a,b)=>String(b.created_at||'').localeCompare(String(a.created_at||'')));$('#connection-label').textContent='Dados salvos neste aparelho';$('.status-dot')?.classList.add('online');render();}
    catch(e){console.error(e);$('#connection-label').textContent='Erro no armazenamento';toast('Não foi possível abrir o banco local: '+e.message);}
  }
  const sum=(arr,key='valor')=>arr.reduce((n,x)=>n+Number(x[key]||0),0);
  function companyName(id){return state.empresas.find(x=>x.id===id)?.razao_social||state.empresas.find(x=>x.id===id)?.nome_fantasia||'Empresa removida';}
  function monthFilter(arr,key='data'){return arr.filter(x=>String(x[key]||'').slice(0,7)===state.month);}
  function stat(label,value,icon,color,foot='',detail=''){return `<article class="stat-card ${detail?'stat-clickable':''}" ${detail?`role="button" tabindex="0" data-dashboard-detail="${detail}"`:''}><div class="stat-top"><span>${label}</span><span class="stat-icon ${color}"><i class="${icon}"></i></span></div><div class="stat-value">${value}</div><div class="stat-foot">${foot}${detail?'<span class="detail-hint"> Toque para detalhar</span>':''}</div></article>`;}
  function panel(title,sub,body,action=''){return `<section class="panel"><div class="panel-head"><div><h2>${title}</h2>${sub?`<p>${sub}</p>`:''}</div>${action}</div>${body}</section>`;}
  function table(headers,rows,empty='Nenhum registro encontrado.'){return `<div class="table-wrap"><table><thead><tr>${headers.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows||`<tr><td colspan="${headers.length}" class="empty">${empty}</td></tr>`}</tbody></table></div>`;}
  function render(){
    $('#page-title').textContent=titles[state.page]||'Visão geral';
    document.querySelectorAll('.nav-link').forEach(x=>x.classList.toggle('active',x.dataset.page===state.page));
    const root=$('#page-content');
    const pages={dashboard:dashboard,empresas:companies,diarias:diaries,notas:invoices,recebiveis:payments,relatorios:reports,configuracoes:settings};
    root.innerHTML=(pages[state.page]||dashboard)();
    bindPage();
  }
  function dashboard(){
    const d=monthFilter(state.diarias), n=monthFilter(state.notas), r=monthFilter(state.recebiveis);
    const totalD=sum(d,'valor_total'), paidD=sum(d.filter(x=>(x.status_pagamento||'Pendente')==='Pago'),'valor_total');
    const pendingD=Math.max(0,totalD-paidD), totalN=sum(n), totalR=sum(r);
    const rows=state.empresas.map(e=>{
      const ds=d.filter(x=>x.empresa_id===e.id),ns=n.filter(x=>x.empresa_id===e.id),rs=r.filter(x=>x.empresa_id===e.id);
      const td=sum(ds,'valor_total'),pd=sum(ds.filter(x=>(x.status_pagamento||'Pendente')==='Pago'),'valor_total');
      return `<tr class="clickable-row" data-company-detail="${e.id}" tabindex="0"><td><b>${esc(e.nome_fantasia||e.razao_social)}</b><div class="hint">${esc(e.cnpj||'')}</div></td><td>${ds.length} • ${money(td)}</td><td class="green">${money(pd)}</td><td class="amber">${money(Math.max(0,td-pd))}</td><td>${money(sum(ns))}</td><td class="green">${money(sum(rs))}</td><td class="amber">${money(Math.max(0,sum(ns)-sum(rs)))}</td></tr>`;
    }).join('');
    const recent=[...d].sort((a,b)=>String(b.data||'').localeCompare(String(a.data||''))).slice(0,8).map(x=>`<tr><td>${dateBR(x.data)}</td><td>${esc(companyName(x.empresa_id))}</td><td>${money(x.valor_total)}</td><td><span class="pill ${(x.status_pagamento||'Pendente')==='Pago'?'green':'amber'}">${esc(x.status_pagamento||'Pendente')}</span></td></tr>`).join('');
    const detail=state.selectedCompanyDetail ? companyDetail(state.selectedCompanyDetail) : (state.dashboardDetail ? dashboardDetail(state.dashboardDetail) : '');
    return `<div class="toolbar dashboard-filter"><span class="hint">Indicadores do mês selecionado</span><input class="field month-input" type="month" id="month-filter" value="${state.month}"></div>
    <div class="grid-stats">
      ${stat('TOTAL DE DIÁRIAS',money(totalD),'fa-solid fa-route','blue',`${d.length} lançamento(s)`,'diarias')}
      ${stat('DIÁRIAS PAGAS',money(paidD),'fa-solid fa-circle-check','green','Marcadas como pagas','pagas')}
      ${stat('DIÁRIAS PENDENTES',money(pendingD),'fa-solid fa-hourglass-half','amber','Aguardando pagamento','pendentes')}
      ${stat('NOTAS FISCAIS',money(totalN),'fa-solid fa-file-invoice','blue',`${n.length} nota(s)`,'notas')}
      ${stat('RECEBIDO EM PAGAMENTOS',money(totalR),'fa-solid fa-wallet','green',`${r.length} recebimento(s)`,'recebiveis')}
      ${stat('SALDO DE NFs',money(Math.max(0,totalN-totalR)),'fa-solid fa-file-invoice-dollar','amber','NFs menos recebimentos','saldo')}
    </div>
    ${panel('Empresas cadastradas','Toque em uma empresa para abrir o extrato completo',table(['Empresa','Diárias / total','Pagas','Pendentes','Notas fiscais','Recebido','Saldo de NFs'],rows,'Cadastre uma empresa para começar.'))}
    ${detail}
    <div class="two-col">${panel('Atalhos','Ações rápidas',`<div class="grid gap-2"><button class="secondary-btn" data-open="empresa"><i class="fa-solid fa-building"></i> Cadastrar empresa</button><button class="secondary-btn" data-open="diaria"><i class="fa-solid fa-calendar-plus"></i> Lançar diária</button><button class="secondary-btn" data-open="nota"><i class="fa-solid fa-file-circle-plus"></i> Registrar nota fiscal</button><button class="secondary-btn" data-open="recebivel"><i class="fa-solid fa-money-bill"></i> Registrar recebimento</button></div>`)}
    ${panel('Últimas diárias','Lançamentos do mês selecionado',table(['Data','Empresa','Valor','Situação'],recent,'Nenhuma diária registrada neste mês.'))}</div>`;
  }
  function dashboardDetail(type){
    const labels={diarias:'Todas as diárias do mês',pagas:'Diárias pagas do mês',pendentes:'Diárias pendentes do mês',notas:'Notas fiscais do mês',recebiveis:'Recebimentos do mês',saldo:'Resumo de saldo por empresa'};
    const d=monthFilter(state.diarias), n=monthFilter(state.notas), r=monthFilter(state.recebiveis);
    let rows='', headers=[];
    if(type==='diarias'||type==='pagas'||type==='pendentes'){
      const list=d.filter(x=>type==='diarias'||(type==='pagas'?(x.status_pagamento||'Pendente')==='Pago':(x.status_pagamento||'Pendente')!=='Pago'));
      headers=['Data','Empresa','Quantidade','Valor','Situação'];
      rows=list.map(x=>`<tr><td>${dateBR(x.data)}</td><td>${esc(companyName(x.empresa_id))}</td><td>${esc(x.quantidade||1)}</td><td>${money(x.valor_total)}</td><td>${esc(x.status_pagamento||'Pendente')}</td></tr>`).join('');
    } else if(type==='notas'){
      headers=['Emissão','Empresa','Número','Valor','Status'];
      rows=n.map(x=>`<tr><td>${dateBR(x.data_emissao)}</td><td>${esc(companyName(x.empresa_id))}</td><td>${esc(x.numero||'—')}</td><td>${money(x.valor)}</td><td>${esc(x.status||'Emitida')}</td></tr>`).join('');
    } else if(type==='recebiveis'){
      headers=['Data','Empresa','Forma','Valor','Observações'];
      rows=r.map(x=>`<tr><td>${dateBR(x.data)}</td><td>${esc(companyName(x.empresa_id))}</td><td>${esc(x.forma_pagamento||'—')}</td><td>${money(x.valor)}</td><td>${esc(x.observacoes||'—')}</td></tr>`).join('');
    } else {
      headers=['Empresa','Diárias','Pagas','Pendentes','Notas','Recebido','Saldo NFs'];
      rows=state.empresas.map(e=>{const ds=d.filter(x=>x.empresa_id===e.id),ns=n.filter(x=>x.empresa_id===e.id),rs=r.filter(x=>x.empresa_id===e.id);const td=sum(ds,'valor_total'),pd=sum(ds.filter(x=>(x.status_pagamento||'Pendente')==='Pago'),'valor_total');return `<tr><td>${esc(e.nome_fantasia||e.razao_social)}</td><td>${money(td)}</td><td>${money(pd)}</td><td>${money(td-pd)}</td><td>${money(sum(ns))}</td><td>${money(sum(rs))}</td><td>${money(Math.max(0,sum(ns)-sum(rs)))}</td></tr>`}).join('');
    }
    return panel(labels[type]||'Detalhamento',`Detalhamento dos registros de ${state.month}`,`<div class="detail-toolbar"><span class="hint">Registros encontrados: ${type==='diarias'?d.length:type==='pagas'?d.filter(x=>(x.status_pagamento||'Pendente')==='Pago').length:type==='pendentes'?d.filter(x=>(x.status_pagamento||'Pendente')!=='Pago').length:type==='notas'?n.length:type==='recebiveis'?r.length:state.empresas.length}</span><button class="mini-btn" data-close-detail>Fechar</button></div>${table(headers,rows)}`);
  }
  function companyDetail(id){
    const e=state.empresas.find(x=>x.id===id); if(!e)return '';
    const ds=state.diarias.filter(x=>x.empresa_id===id).sort((a,b)=>String(b.data||'').localeCompare(String(a.data||'')));
    const ns=state.notas.filter(x=>x.empresa_id===id).sort((a,b)=>String(b.data_emissao||'').localeCompare(String(a.data_emissao||'')));
    const rs=state.recebiveis.filter(x=>x.empresa_id===id).sort((a,b)=>String(b.data||'').localeCompare(String(a.data||'')));
    const td=sum(ds,'valor_total'),pd=sum(ds.filter(x=>(x.status_pagamento||'Pendente')==='Pago'),'valor_total');
    const diaryRows=ds.map(x=>`<tr><td>${dateBR(x.data)}</td><td>${esc(x.veiculo_tipo||'—')}</td><td>${esc(x.rota||'—')}</td><td>${esc(x.quantidade||1)}</td><td>${money(x.valor_total)}</td><td><span class="pill ${(x.status_pagamento||'Pendente')==='Pago'?'green':'amber'}">${esc(x.status_pagamento||'Pendente')}</span></td></tr>`).join('');
    const invoiceRows=ns.map(x=>`<tr><td>${esc(x.numero||'—')}</td><td>${dateBR(x.data_emissao)}</td><td>${money(x.valor)}</td><td>${esc(x.status||'Emitida')}</td></tr>`).join('');
    const paymentRows=rs.map(x=>`<tr><td>${dateBR(x.data)}</td><td>${esc(x.forma_pagamento||'—')}</td><td>${money(x.valor)}</td><td>${esc(x.observacoes||'—')}</td></tr>`).join('');
    return `<section class="company-detail panel"><div class="panel-head"><div><h2>Extrato: ${esc(e.nome_fantasia||e.razao_social)}</h2><p>${esc(e.razao_social||'')} • CNPJ ${esc(e.cnpj||'—')}</p></div><button class="mini-btn" data-close-detail>Fechar</button></div>
      <div class="grid-stats detail-stats">${stat('TOTAL EM DIÁRIAS',money(td),'fa-solid fa-route','blue',`${ds.length} lançamento(s)`)}${stat('DIÁRIAS PAGAS',money(pd),'fa-solid fa-circle-check','green')}${stat('DIÁRIAS PENDENTES',money(td-pd),'fa-solid fa-hourglass-half','amber')}${stat('NOTAS FISCAIS',money(sum(ns)),'fa-solid fa-file-invoice','blue',`${ns.length} nota(s)`)}${stat('RECEBIDO',money(sum(rs)),'fa-solid fa-wallet','green',`${rs.length} recebimento(s)`)}${stat('SALDO DE NFs',money(Math.max(0,sum(ns)-sum(rs))),'fa-solid fa-file-invoice-dollar','amber')}</div>
      ${panel('Diárias realizadas','Histórico completo desta empresa',table(['Data','Veículo','Rota / observação','Qtd.','Valor','Situação'],diaryRows))}
      ${panel('Notas fiscais','Notas emitidas para esta empresa',table(['Número','Emissão','Valor','Status'],invoiceRows))}
      ${panel('Recebimentos','Pagamentos registrados para esta empresa',table(['Data','Forma','Valor','Observações'],paymentRows))}
    </section>`;
  }
  function companies(){
    const q=($('#search')?.value||'').toLowerCase();
    const rows=state.empresas.filter(e=>(e.razao_social+' '+e.nome_fantasia+' '+e.cnpj).toLowerCase().includes(q)).map(e=>`<tr><td><b>${esc(e.nome_fantasia||e.razao_social)}</b><div class="hint">${esc(e.razao_social||'')}</div></td><td>${esc(e.cnpj||'—')}</td><td>${esc(e.telefone||'—')}</td><td>${esc(e.email||'—')}</td><td><div class="actions"><button class="mini-btn" data-edit="empresa" data-id="${e.id}"><i class="fa fa-pen"></i></button><button class="mini-btn" data-delete="empresas" data-id="${e.id}"><i class="fa fa-trash"></i></button></div></td></tr>`).join('');
    return panel('Empresas tomadoras','Cadastre e mantenha os dados das empresas contratantes',`<div class="toolbar" style="margin-bottom:14px"><input id="search" class="search" placeholder="Buscar empresa ou CNPJ"><button class="primary-btn" data-open="empresa"><i class="fa fa-plus"></i> Nova empresa</button></div>${table(['Empresa','CNPJ','Telefone','E-mail','Ações'],rows,'Cadastre sua primeira empresa.')}`);
  }
  function diaries(){
    const rows=monthFilter(state.diarias).map(x=>`<tr><td>${dateBR(x.data)}</td><td>${esc(companyName(x.empresa_id))}</td><td>${esc(x.veiculo_tipo||'—')}</td><td>${esc(x.rota||'—')}</td><td>${money(x.valor_total)}</td><td><span class="pill ${(x.status_pagamento||'Pendente')==='Pago'?'green':'amber'}">${esc(x.status_pagamento||'Pendente')}</span></td><td><button class="mini-btn" data-edit="diaria" data-id="${x.id}" title="Editar situação"><i class="fa fa-pen"></i></button> <button class="mini-btn" data-delete="diarias" data-id="${x.id}"><i class="fa fa-trash"></i></button></td></tr>`).join('');
    return panel('Diárias trabalhadas','Histórico de serviços e viagens',`<div class="toolbar" style="margin-bottom:14px"><input class="field month-input" type="month" id="month-filter" value="${state.month}"><button class="primary-btn" data-open="diaria"><i class="fa fa-plus"></i> Nova diária</button></div>${table(['Data','Empresa','Veículo','Rota / observação','Valor','Situação','Ações'],rows)}`);
  }
  function invoices(){
    const rows=state.notas.map(x=>`<tr><td>${esc(x.numero||'—')}</td><td>${dateBR(x.data_emissao)}</td><td>${esc(companyName(x.empresa_id))}</td><td>${money(x.valor)}</td><td>${esc(x.status||'Emitida')}</td><td>${x.comprovante?`<a class="mini-btn" href="${x.comprovante.dataUrl}" download="${esc(x.comprovante.name)}">Ver arquivo</a>`:'—'}</td><td><button class="mini-btn" data-delete="notas_fiscais" data-id="${x.id}"><i class="fa fa-trash"></i></button></td></tr>`).join('');
    return panel('Notas fiscais','Registre as notas emitidas e seus valores',`<div class="toolbar" style="margin-bottom:14px"><button class="primary-btn" data-open="nota"><i class="fa fa-plus"></i> Nova nota fiscal</button></div>${table(['Número','Emissão','Empresa','Valor','Status','Comprovante','Ações'],rows)}`);
  }
  function payments(){
    const rows=state.recebiveis.map(x=>`<tr><td>${dateBR(x.data)}</td><td>${esc(companyName(x.empresa_id))}</td><td>${esc(x.forma_pagamento||'—')}</td><td>${money(x.valor)}</td><td>${esc(x.observacoes||'—')}</td><td>${x.comprovante?`<a class="mini-btn" href="${x.comprovante.dataUrl}" download="${esc(x.comprovante.name)}">Ver arquivo</a>`:'—'}</td><td><button class="mini-btn" data-delete="recebiveis" data-id="${x.id}"><i class="fa fa-trash"></i></button></td></tr>`).join('');
    return panel('Recebimentos','Acompanhe pagamentos e conciliação',`<div class="toolbar" style="margin-bottom:14px"><button class="primary-btn" data-open="recebivel"><i class="fa fa-plus"></i> Novo recebimento</button></div>${table(['Data','Empresa','Forma','Valor','Observações','Comprovante','Ações'],rows)}`);
  }
  function paymentDueForDiary(d,company){
    const date=String(d.data||''); if(!/^\d{4}-\d{2}-\d{2}$/.test(date)) return '';
    const [y,m,day]=date.split('-').map(Number); const rule=company?.regra_pagamento||'quinzenal_05_20';
    let dueMonth=m, dueDay=5; if(day>=16) dueDay=20; dueMonth+=1; if(dueMonth>12){dueMonth=1; y+=1;}
    if(rule==='mensal_05'){dueDay=5; dueMonth=m+1; if(dueMonth>12){dueMonth=1;y+=1;}}
    if(rule==='mensal_20'){dueDay=20; dueMonth=m+1; if(dueMonth>12){dueMonth=1;y+=1;}}
    return `${String(dueDay).padStart(2,'0')}/${String(dueMonth).padStart(2,'0')}/${y}`;
  }
  function paymentRuleLabel(company){const r=company?.regra_pagamento||'quinzenal_05_20';return r==='mensal_05'?'Mensal — dia 5 do mês seguinte':r==='mensal_20'?'Mensal — dia 20 do mês seguinte':'Quinzenal — 1 a 15 no dia 5; 16 ao fim no dia 20 do mês seguinte';}
  function reportCompanyDetail(id){
    const e=state.empresas.find(x=>x.id===id); if(!e)return '';
    const ds=state.diarias.filter(x=>x.empresa_id===id).sort((a,b)=>String(a.data||'').localeCompare(String(b.data||'')));
    const ns=state.notas.filter(x=>x.empresa_id===id).sort((a,b)=>String(a.data_emissao||'').localeCompare(String(b.data_emissao||'')));
    const rs=state.recebiveis.filter(x=>x.empresa_id===id).sort((a,b)=>String(a.data||'').localeCompare(String(b.data||'')));
    const totalServ=sum(ds,'valor_total'), totalRecebido=sum(rs,'valor'), saldo=Math.max(0,totalServ-totalRecebido), totalNF=sum(ns,'valor');
    const months=[...new Set(ds.map(x=>String(x.data||'').slice(0,7)).filter(m=>/^\d{4}-\d{2}$/.test(m)))].sort();
    const monthLabel=m=>new Date(`${m}-15T12:00:00`).toLocaleDateString('pt-BR',{month:'long',year:'numeric'});
    const nextMonthDate=(m,day)=>{const [yy,mm]=m.split('-').map(Number);const dt=new Date(yy,mm,day,12);return dt.toLocaleDateString('pt-BR');};
    let running=0;
    const periodRows=months.map(m=>{
      const md=ds.filter(x=>String(x.data||'').startsWith(m));
      const first=md.filter(x=>Number(String(x.data||'').slice(8,10))<=15);
      const second=md.filter(x=>Number(String(x.data||'').slice(8,10))>=16);
      const firstVal=sum(first,'valor_total'), secondVal=sum(second,'valor_total'), monthTotal=firstVal+secondVal;
      running+=monthTotal;
      const rule=e.regra_pagamento||'quinzenal_05_20';
      const firstDue=rule==='mensal_20'?nextMonthDate(m,20):nextMonthDate(m,5);
      const secondDue=rule==='mensal_05'?nextMonthDate(m,5):nextMonthDate(m,20);
      const firstLabel=rule==='mensal_05'?'Mês — venc. dia 5':rule==='mensal_20'?'Mês — venc. dia 20':'1ª quinzena — venc. dia 5';
      const secondLabel=rule==='mensal_05'?'Incluído no mês — dia 5':rule==='mensal_20'?'Incluído no mês — dia 20':'2ª quinzena — venc. dia 20';
      return `<tr><td rowspan="2"><b>${esc(monthLabel(m))}</b></td><td>${esc(firstLabel)}</td><td>${first.length}</td><td>${money(firstVal)}</td><td>${esc(firstDue)}</td></tr><tr><td>${esc(secondLabel)}</td><td>${second.length}</td><td>${money(secondVal)}</td><td>${esc(secondDue)}</td></tr><tr class="subtotal-row"><td colspan="2">Total de serviços no mês</td><td>${md.length}</td><td><b>${money(monthTotal)}</b></td><td>Acumulado: ${money(running)}</td></tr>`;
    }).join('');
    const attachments=x=>x?.comprovante?`<a class="mini-btn" href="${x.comprovante.dataUrl}" download="${esc(x.comprovante.name)}" target="_blank"><i class="fa-solid fa-paperclip"></i> ${esc(x.comprovante.name)}</a>`:'—';
    const diaryRows=[...ds].reverse().map(x=>`<tr><td>${dateBR(x.data)}</td><td>${money(x.valor_total)}</td><td>${esc(x.status_pagamento||'Pendente')}</td><td>${esc(paymentDueForDiary(x,e)||'—')}</td><td>${esc(x.rota||'—')}</td></tr>`).join('');
    const invoiceRows=[...ns].reverse().map(x=>`<tr><td>${esc(x.numero||'—')}</td><td>${dateBR(x.data_emissao)}</td><td>${money(x.valor)}</td><td>${attachments(x)}</td></tr>`).join('');
    const paymentRows=[...rs].reverse().map(x=>`<tr><td>${dateBR(x.data)}</td><td>${esc(x.forma_pagamento||'—')}</td><td>${money(x.valor)}</td><td>${attachments(x)}</td><td>${esc(x.observacoes||'—')}</td></tr>`).join('');
    return `<section class="panel company-report-detail"><div class="panel-head"><div><h2>Extrato financeiro: ${esc(e.nome_fantasia||e.razao_social)}</h2><p>${esc(e.razao_social||'')} • CNPJ ${esc(e.cnpj||'—')}</p><p class="hint">Regra de recebimento: ${esc(paymentRuleLabel(e))}</p></div><button class="mini-btn" data-close-report>Fechar extrato</button></div>
      <div class="grid-stats detail-stats">${stat('TOTAL DE SERVIÇOS',money(totalServ),'fa-solid fa-route','blue',`${ds.length} diária(s)`)}${stat('TOTAL RECEBIDO',money(totalRecebido),'fa-solid fa-wallet','green',`${rs.length} pagamento(s)`)}${stat('SALDO A RECEBER',money(saldo),'fa-solid fa-hourglass-half','amber','Serviços menos recebimentos')}${stat('NOTAS FISCAIS',money(totalNF),'fa-solid fa-file-invoice','blue',`${ns.length} nota(s) emitida(s)`)}</div>
      ${panel('Previsão de recebimento por período','Valores calculados a partir das diárias realmente lançadas. As datas previstas seguem a regra configurada para esta empresa.',table(['Mês trabalhado','Período','Diárias','Valor previsto','Data prevista'],periodRows,'Nenhuma diária lançada para esta empresa.'))}
      ${panel('Histórico de serviços','Cada lançamento de diária desta empresa',table(['Data trabalhada','Valor','Situação','Pagamento previsto','Rota / observação'],diaryRows))}
      ${panel('Notas fiscais e comprovantes','Documentos anexados às notas',table(['Número','Emissão','Valor','Arquivo'],invoiceRows))}
      ${panel('Recebimentos e comprovantes','Pagamentos registrados. Os recebimentos são exibidos por data; ainda não são vinculados automaticamente a uma quinzena específica.',table(['Data','Forma','Valor','Comprovante','Observações'],paymentRows))}</section>`;
  }
  function reports(){const companyRows=state.empresas.map(e=>{const ds=state.diarias.filter(x=>x.empresa_id===e.id),rs=state.recebiveis.filter(x=>x.empresa_id===e.id),earned=sum(ds,'valor_total'),received=sum(rs,'valor');return `<tr class="clickable-row" data-report-company="${e.id}" tabindex="0"><td><b>${esc(e.nome_fantasia||e.razao_social)}</b><div class="hint">${esc(e.cnpj||'')}</div><button type="button" class="mini-btn report-open-btn" data-report-company="${e.id}">Abrir extrato <i class="fa-solid fa-arrow-right"></i></button></td><td>${money(earned)}</td><td class="green">${money(received)}</td><td class="amber">${money(Math.max(0,earned-received))}</td></tr>`}).join('');return `<div class="grid-stats">${stat('EMPRESAS',state.empresas.length,'fa-solid fa-building','blue','Tomadoras cadastradas')}${stat('DIÁRIAS',state.diarias.length,'fa-solid fa-route','green','Lançamentos totais')}${stat('NOTAS FISCAIS',state.notas.length,'fa-solid fa-file-invoice','blue','Registros totais')}${stat('RECEBIMENTOS',state.recebiveis.length,'fa-solid fa-wallet','green','Registros totais')}</div>${panel('Relatório financeiro por empresa','Toque na empresa para consultar o detalhamento mensal e acumulado',table(['Empresa','Serviços realizados','Recebido','Saldo pendente'],companyRows,'Cadastre uma empresa para visualizar seu relatório.'))}${state.selectedReportCompany?reportCompanyDetail(state.selectedReportCompany):''}${panel('Gerador de relatórios personalizados','Escolha empresa, período e informações para o JPG ou PDF',`<div class=\"report-builder\"><div class=\"form-field\"><label>Empresa</label><select id=\"custom-report-company\" class=\"field\"><option value=\"\">Todas as empresas</option>${state.empresas.map(e=>`<option value=\"${e.id}\">${esc(e.nome_fantasia||e.razao_social)}</option>`).join('')}</select></div><div class=\"form-field\"><label>Período</label><select id=\"custom-report-period\" class=\"field\"><option value=\"first\">1ª quinzena (1 a 15)</option><option value=\"second\">2ª quinzena (16 ao fim)</option><option value=\"month\" selected>Mês completo</option></select></div><div class=\"form-field\"><label>Mês de referência</label><input type=\"month\" id=\"custom-report-month\" class=\"field\" value=\"${state.month}\"></div><div class=\"report-options\"><label><input type=\"checkbox\" id=\"report-include-dates\" checked> Datas trabalhadas</label><label><input type=\"checkbox\" id=\"report-include-values\" checked> Valores das diárias</label><label><input type=\"checkbox\" id=\"report-include-due\" checked> Previsões de recebimento</label><label><input type=\"checkbox\" id=\"report-include-status\" checked> Pago/pendente</label><label><input type=\"checkbox\" id=\"report-include-summary\" checked> Resumo financeiro</label></div><div class=\"toolbar\"><button class=\"primary-btn\" id=\"custom-report-jpg\">Gerar JPG personalizado</button><button class=\"secondary-btn\" id=\"custom-report-pdf\">Gerar PDF personalizado</button></div><div id=\"custom-report-preview\ class=\"custom-report-preview\"><p class=\"hint\">Configure os dados e gere o relatório.</p></div></div>`)}${panel('Exportação de dados','Exporte todos os registros ou relatórios para conferência',`<div class="toolbar"><button class="primary-btn" id="export-xlsx"><i class="fa-solid fa-file-excel"></i> Exportar Excel completo</button><button class="secondary-btn" id="export-json"><i class="fa-solid fa-file-shield"></i> Backup completo (JSON)</button><button class="secondary-btn" id="export-pdf"><i class="fa-solid fa-file-pdf"></i> Exportar PDF</button><button class="secondary-btn" id="export-jpg"><i class="fa-solid fa-image"></i> Exportar JPG</button></div><div class="form-field" style="margin-top:18px"><label>Restaurar dados de um arquivo do aparelho ou Google Drive</label><input id="import-backup-file" class="field" type="file" accept=".json,.xlsx,.xls,application/json,application/vnd.openxmlformats-officedocument.spreadsheetml.sheet"></div><p class="hint" style="margin-top:14px">O Excel exporta os dados tabulares. Para preservar também os arquivos anexados, use o backup completo JSON ou Google Drive.</p>`)}`;}
  function bindPage(){
    $('#month-filter')?.addEventListener('change',e=>{state.month=e.target.value;state.dashboardDetail=null;render()});
    document.querySelectorAll('[data-dashboard-detail]').forEach(el=>{const open=()=>{state.dashboardDetail=el.dataset.dashboardDetail;render();};el.addEventListener('click',open);el.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();open();}});});
    document.querySelectorAll('[data-company-detail]').forEach(el=>{const open=()=>{state.selectedCompanyDetail=el.dataset.companyDetail;state.dashboardDetail=null;render();const detail=$('.company-detail');detail?.scrollIntoView({behavior:'smooth',block:'start'});};el.addEventListener('click',open);el.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();open();}});});
    document.querySelectorAll('[data-close-detail]').forEach(el=>el.addEventListener('click',()=>{state.dashboardDetail=null;state.selectedCompanyDetail=null;render();}));
    document.querySelectorAll('[data-report-company]').forEach(el=>{const open=e=>{e?.stopPropagation?.();state.selectedReportCompany=el.dataset.reportCompany;render();$('.company-report-detail')?.scrollIntoView({behavior:'smooth',block:'start'});};el.addEventListener('click',open);el.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();open(e);}});});
    document.querySelectorAll('[data-close-report]').forEach(el=>el.addEventListener('click',()=>{state.selectedReportCompany=null;render();}));
    $('#search')?.addEventListener('input',()=>{const p=$('#search').selectionStart;render();$('#search').focus();$('#search').setSelectionRange(p,p)});
    document.querySelectorAll('[data-open]').forEach(b=>b.onclick=()=>openForm(b.dataset.open));
    document.querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>openForm(b.dataset.edit,b.dataset.id));
    document.querySelectorAll('[data-delete]').forEach(b=>b.onclick=()=>removeRow(b.dataset.delete,b.dataset.id));
    $('#custom-report-jpg')?.addEventListener('click',()=>generateCustomReport('jpg'));
    $('#custom-report-pdf')?.addEventListener('click',()=>generateCustomReport('pdf'));
    $('#export-xlsx')?.addEventListener('click',exportExcel);
    $('#export-json')?.addEventListener('click',downloadJSONBackup);
    $('#settings-export-json')?.addEventListener('click',downloadJSONBackup);
    $('#settings-export-xlsx')?.addEventListener('click',exportExcel);
    $('#settings-import-file')?.addEventListener('change',e=>{if(e.target.files?.[0])importBackupFile(e.target.files[0]);});
    $('#import-backup-file')?.addEventListener('change',e=>{if(e.target.files?.[0])importBackupFile(e.target.files[0]);});
    $('#export-pdf')?.addEventListener('click',()=>capture('pdf'));
    $('#export-jpg')?.addEventListener('click',()=>capture('jpg'));
    $('#connect-drive')?.addEventListener('click',connectDrive);
    $('#backup-drive')?.addEventListener('click',createBackup);
    $('#refresh-backups')?.addEventListener('click',listBackups);
    $('#restore-backup')?.addEventListener('change',e=>{if(e.target.value)restoreBackup(e.target.value);});
    $('#save-config')?.addEventListener('click',saveDriveConfig);
    $('#disconnect-drive')?.addEventListener('click',disconnectDrive);
  }
  const field=(label,name,type='text',value='',full=false,extra='')=>`<div class="form-field ${full?'full':''}"><label>${label}</label><input class="field" name="${name}" type="${type}" value="${esc(value??'')}" ${extra}></div>`;
  const selectCompany=(value='')=>`<div class="form-field full"><label>Empresa tomadora *</label><select class="field" name="empresa_id" required><option value="">Selecione uma empresa</option>${state.empresas.map(e=>`<option value="${e.id}" ${e.id===value?'selected':''}>${esc(e.nome_fantasia||e.razao_social)}</option>`).join('')}</select></div>`;
  function fileAsDataURL(file){return new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve({name:file.name,type:file.type||'application/octet-stream',size:file.size,dataUrl:String(reader.result)});reader.onerror=()=>reject(reader.error||new Error('Falha ao ler o arquivo.'));reader.readAsDataURL(file);});}
  function openForm(kind,id=null){
    const map={empresa:['empresas','Nova empresa'],diaria:['diarias','Nova diária'],nota:['notas_fiscais','Nova nota fiscal'],recebivel:['recebiveis','Novo recebimento']};
    const [table,title]=map[kind], existing=id?state[kind==='empresa'?'empresas':kind==='diaria'?'diarias':kind==='nota'?'notas':'recebiveis'].find(x=>x.id===id):{};
    let body='';
    if(kind==='empresa')body=field('CNPJ','cnpj','text',existing?.cnpj,false,'maxlength="18" inputmode="numeric" autocomplete="off" placeholder="Digite os 14 números do CNPJ"')+`<div class="form-field full"><button type="button" class="secondary-btn" id="lookup-cnpj"><i class="fa-solid fa-magnifying-glass"></i> Consultar CNPJ</button><p class="hint">Digite o CNPJ e toque em consultar para preencher os dados automaticamente.</p></div>`+field('Razão social','razao_social','text',existing?.razao_social)+field('Nome fantasia','nome_fantasia','text',existing?.nome_fantasia)+field('Telefone','telefone','tel',existing?.telefone)+field('E-mail','email','email',existing?.email)+`<div class="form-field full"><label>Regra de recebimento / pagamento</label><select class="field" name="regra_pagamento"><option value="quinzenal_05_20" ${(!existing?.regra_pagamento||existing.regra_pagamento==='quinzenal_05_20')?'selected':''}>Quinzenal: dias 1–15 recebem dia 5; dias 16–fim recebem dia 20 (mês seguinte)</option><option value="mensal_05" ${existing?.regra_pagamento==='mensal_05'?'selected':''}>Mensal: receber no dia 5 do mês seguinte</option><option value="mensal_20" ${existing?.regra_pagamento==='mensal_20'?'selected':''}>Mensal: receber no dia 20 do mês seguinte</option></select><p class="hint">Configure a regra de cada empresa. Você só registra as diárias dos dias realmente trabalhados.</p></div>`+field('Observações','observacoes','text',existing?.observacoes,true);
    if(kind==='diaria'){const rates=[...new Set(state.diarias.map(x=>Number(x.valor_diaria)).filter(v=>Number.isFinite(v)&&v>0))].sort((a,b)=>b-a);body=selectCompany(existing?.empresa_id)+field('Data do serviço','data','date',existing?.data||today)+`<div class="form-field"><label>Tipo de veículo</label><select name="veiculo_tipo" class="field">${['Carro','Van','Ônibus','Caminhão','Outro'].map(v=>`<option ${existing?.veiculo_tipo===v?'selected':''}>${v}</option>`).join('')}</select></div>`+`<div class="form-field"><label>Valor da diária (R$)</label><input class="field" name="valor_diaria" type="number" list="saved-daily-rates" value="${esc(existing?.valor_diaria??'')}" step="0.01" min="0" inputmode="decimal" required placeholder="Digite ou selecione um valor"><datalist id="saved-daily-rates">${rates.map(v=>`<option value="${v.toFixed(2)}">`).join('')}</datalist><p class="hint">Valores já utilizados ficam disponíveis para selecionar nos próximos lançamentos.</p></div>`+field('Quantidade de diárias','quantidade','number',existing?.quantidade||1,false,'min="0.5" step="0.5" required')+`<div class="form-field"><label>Situação do pagamento</label><select name="status_pagamento" class="field"><option ${(!existing?.status_pagamento||existing.status_pagamento==='Pendente')?'selected':''}>Pendente</option><option ${existing?.status_pagamento==='Pago'?'selected':''}>Pago</option></select></div>`+field('Rota / observações','rota','text',existing?.rota,true); }
    if(kind==='nota')body=selectCompany(existing?.empresa_id)+field('Número da NF','numero','text',existing?.numero)+field('Data de emissão','data_emissao','date',existing?.data_emissao||today)+field('Valor da nota (R$)','valor','number',existing?.valor||'','', 'step="0.01" min="0" required')+field('Status','status','text',existing?.status||'Emitida')+`<div class="form-field full"><label>Comprovante da nota fiscal (PDF ou imagem)</label><input class="field" name="comprovante_file" type="file" accept="application/pdf,image/*"><p class="hint">Anexe o PDF ou uma foto da nota. Limite recomendado: 12 MB.</p>${existing?.comprovante?`<p class="hint">Arquivo atual: ${esc(existing.comprovante.name)} (será mantido se não selecionar outro).</p>`:''}</div>`;
    if(kind==='recebivel')body=selectCompany(existing?.empresa_id)+field('Data do recebimento','data','date',existing?.data||today)+field('Valor recebido (R$)','valor','number',existing?.valor||'','', 'step="0.01" min="0" required')+`<div class="form-field"><label>Forma de pagamento</label><select name="forma_pagamento" class="field"><option>Pix</option><option>Transferência</option><option>Depósito</option><option>Dinheiro</option><option>Outro</option></select></div>`+`<div class="form-field full"><label>Comprovante do pagamento (PDF ou imagem)</label><input class="field" name="comprovante_file" type="file" accept="application/pdf,image/*"><p class="hint">Anexe o comprovante Pix, transferência, depósito ou foto. Limite recomendado: 12 MB.</p>${existing?.comprovante?`<p class="hint">Arquivo atual: ${esc(existing.comprovante.name)} (será mantido se não selecionar outro).</p>`:''}</div>`+field('Observações','observacoes','text',existing?.observacoes,true);
    $('#modal-root').innerHTML=`<div class="modal-backdrop"><div class="modal"><h2>${title}</h2><p class="modal-sub">Preencha os dados abaixo. Campos com * são obrigatórios.</p><form id="record-form"><div class="form-grid">${body}</div><div class="modal-actions"><button type="button" class="secondary-btn" id="cancel-modal">Cancelar</button><button class="primary-btn" type="submit">Salvar registro</button></div></form></div></div>`;
    $('#cancel-modal').onclick=()=>$('#modal-root').innerHTML='';
    $('#lookup-cnpj')?.addEventListener('click',()=>lookupCNPJ($('#record-form [name="cnpj"]')?.value||''));
    requestAnimationFrame(()=>$('#record-form input:not([type=date]), #record-form select')?.focus());
    $('#record-form').onsubmit=async e=>{e.preventDefault();const form=e.target;const file=form.querySelector('[name="comprovante_file"]')?.files?.[0];const data=Object.fromEntries(new FormData(form).entries());delete data.comprovante_file;Object.keys(data).forEach(k=>{if(data[k]==='')data[k]=null});const oldRecord=id?(state[kind==='nota'?'notas':kind==='recebivel'?'recebiveis':kind==='empresa'?'empresas':'diarias'].find(x=>x.id===id)):null;data.comprovante=oldRecord?.comprovante||null;if(file){if(file.size>12*1024*1024){toast('O arquivo ultrapassa o limite de 12 MB.');return;}if(!(['application/pdf'].includes(file.type)||file.type.startsWith('image/'))){toast('Envie um arquivo PDF ou imagem.');return;}try{data.comprovante=await fileAsDataURL(file);}catch(err){toast('Não foi possível ler o comprovante: '+err.message);return;}}
      if(kind==='diaria'){data.valor_total=Number(data.valor_diaria)*Number(data.quantidade);data.status_pagamento=data.status_pagamento||'Pendente';}
      for(const k of ['valor','valor_diaria','quantidade','valor_total'])if(data[k]!=null)data[k]=Number(data[k]);
      try{await saveRecord(table,data,id);$('#modal-root').innerHTML='';if(kind==='diaria')state.page='dashboard';toast(kind==='diaria'?'Diária registrada! Valores e situação atualizados na visão geral.':'Registro salvo neste aparelho!');await loadAll();}catch(err){toast('Erro ao salvar: '+err.message);}
    };
  }
  async function removeRow(table,id){if(!confirm('Tem certeza que deseja excluir este registro?'))return;try{await deleteRecord(table,id);toast('Registro excluído.');await loadAll();}catch(e){toast('Erro ao excluir: '+e.message);}}
  function settings(){
    const connected=window.CDDrive?.isConnected()||false;
    const backups=state.driveBackups.map(b=>`<option value="${esc(b.id)}">${esc(b.name)} — ${dateBR(b.modifiedTime)}</option>`).join('');
    return `<section class="panel"><div class="panel-head"><div><h2><i class="fa-solid fa-shield-halved"></i> Backup no aparelho</h2><p>Funciona sem Google Cloud e sem conectar Gmail</p></div></div><div class="toolbar"><button class="primary-btn" id="settings-export-json"><i class="fa-solid fa-download"></i> Baixar backup completo</button><button class="secondary-btn" id="settings-export-xlsx"><i class="fa-solid fa-file-excel"></i> Exportar planilha Excel</button></div><div class="form-field" style="margin-top:16px"><label>Restaurar backup do celular, Downloads ou Google Drive</label><input id="settings-import-file" class="field" type="file" accept=".json,.xlsx,.xls,application/json,application/vnd.openxmlformats-officedocument.spreadsheetml.sheet"></div><p class="hint" style="margin-top:10px">Você pode baixar o arquivo, guardá-lo no Google Drive manualmente e selecionar esse mesmo arquivo aqui quando precisar restaurar. Para restauração completa, prefira JSON; Excel também é aceito.</p></section><div class="two-col"><section class="panel"><div class="panel-head"><div><h2><i class="fa-brands fa-google-drive"></i> Google Drive</h2><p>Conecte seu Gmail para guardar cópias de segurança</p></div><span class="pill ${connected?'green':'amber'}">${connected?'Conectado':'Não conectado'}</span></div><p class="hint">O aplicativo cria arquivos de backup visíveis no seu Meu Drive. Ele só acessa os arquivos que criar com este aplicativo, não seus documentos pessoais.</p><div class="toolbar" style="margin-top:16px"><button class="primary-btn" id="connect-drive">${connected?'Reconectar Gmail':'Conectar meu Gmail'}</button><button class="secondary-btn" id="disconnect-drive">Desconectar</button></div><div class="form-field" style="margin-top:18px"><label>Google OAuth Client ID</label><input id="oauth-client-id" class="field" value="${esc(cfg.GOOGLE_CLIENT_ID||'')}" placeholder="000000000000-abc...apps.googleusercontent.com"></div><button class="secondary-btn" id="save-config" style="margin-top:10px">Salvar configuração neste navegador</button><p class="hint" style="margin-top:12px">O Client ID é uma identificação pública do aplicativo. Nunca coloque senha do Gmail, chave secreta ou client secret aqui.</p></section><section class="panel"><div class="panel-head"><div><h2>Backup e restauração</h2><p>Crie uma cópia agora ou recupere uma anterior</p></div></div><div class="grid" style="gap:10px"><button class="primary-btn" id="backup-drive" ${connected?'':'disabled'}><i class="fa-solid fa-cloud-arrow-up"></i> Fazer backup agora</button><button class="secondary-btn" id="refresh-backups" ${connected?'':'disabled'}><i class="fa-solid fa-rotate"></i> Procurar backups no Drive</button><div class="form-field"><label>Escolha um backup para restaurar</label><select class="field" id="restore-backup" ${connected?'':'disabled'}><option value="">${connected?(backups?'Selecione um backup':'Clique em procurar backups'):'Conecte o Gmail primeiro'}</option>${backups}</select></div></div><p class="hint" style="margin-top:14px">A restauração substitui os dados atuais deste aparelho pelos dados da cópia selecionada. O aplicativo pedirá confirmação antes de fazer isso.</p></section></div><section class="panel"><h2>Onde ficam os dados?</h2><p class="hint">Os cadastros são armazenados no banco local do navegador (IndexedDB). Os backups são arquivos JSON no seu Google Drive, na pasta principal do Meu Drive. Faça backup sempre que terminar lançamentos importantes. A instalação PWA usa o mesmo armazenamento do navegador daquele aparelho.</p></section>`;
  }
  function saveDriveConfig(){const id=$('#oauth-client-id')?.value.trim();if(!id||!id.endsWith('.apps.googleusercontent.com')){toast('Informe um OAuth Client ID válido do Google.');return;}localStorage.setItem('CD_GOOGLE_CLIENT_ID',id);cfg.GOOGLE_CLIENT_ID=id;toast('Client ID salvo neste navegador. Agora toque em Conectar meu Gmail.');}
  async function connectDrive(){try{const id=localStorage.getItem('CD_GOOGLE_CLIENT_ID')||cfg.GOOGLE_CLIENT_ID;if(!id){toast('Primeiro configure o OAuth Client ID abaixo.');return;}window.CDDrive.configure(id);await window.CDDrive.connect();toast('Google Drive conectado com sucesso!');render();await listBackups();}catch(e){console.error(e);toast('Não foi possível conectar: '+e.message);}}
  function disconnectDrive(){window.CDDrive?.disconnect();state.driveBackups=[];toast('Conexão do Google Drive encerrada neste navegador.');render();}
  async function createBackup(){try{const payload=await makeBackupPayload();await window.CDDrive.uploadBackup(payload);toast('Backup enviado ao Google Drive!');await listBackups();}catch(e){console.error(e);toast('Falha no backup: '+e.message);}}
  async function listBackups(){try{state.driveBackups=await window.CDDrive.listBackups();render();if(!state.driveBackups.length)toast('Nenhum backup encontrado no Drive.');}catch(e){toast('Erro ao procurar backups: '+e.message);}}
  async function restoreBackup(fileId){if(!confirm('ATENÇÃO: esta ação substituirá todos os cadastros atuais deste aparelho pelos dados do backup. Deseja continuar?')){render();return;}try{const payload=await window.CDDrive.downloadBackup(fileId);await validateAndRestore(payload);}catch(e){console.error(e);toast('Falha ao restaurar: '+e.message);}}
  async function lookupCNPJ(cnpj){const clean=String(cnpj||'').replace(/\D/g,'');if(clean.length!==14){toast('Digite os 14 números do CNPJ para consultar.');return;}const form=$('#record-form');if(!form)return;const button=form.querySelector('button[type=submit]');try{if(button)button.disabled=true;toast('Consultando CNPJ na BrasilAPI...');const res=await fetch(`https://brasilapi.com.br/api/cnpj/v1/${clean}`);if(!res.ok)throw Error(res.status===404?'CNPJ não encontrado. Confira os números.':'Não foi possível consultar este CNPJ agora.');const d=await res.json();const razao=form.querySelector('[name="razao_social"]'),fantasia=form.querySelector('[name="nome_fantasia"]');if(razao&&!razao.value)razao.value=d.razao_social||'';if(fantasia&&!fantasia.value)fantasia.value=d.nome_fantasia||'';toast('Dados encontrados. Confira e complete o cadastro.');}catch(e){toast(e.message||'Falha na consulta do CNPJ.');}finally{if(button)button.disabled=false;}}
  function exportExcel(){if(!window.XLSX){toast('Biblioteca Excel indisponível. Verifique a internet e tente novamente.');return;}const wb=XLSX.utils.book_new();for(const [key,label] of [['empresas','Empresas'],['diarias','Diarias'],['notas','Notas Fiscais'],['recebiveis','Recebimentos']]){const data=state[key].map(x=>{const row={...x,empresa_nome:x.empresa_id?companyName(x.empresa_id):''};if(row.comprovante){row.comprovante_arquivo=row.comprovante.name;row.comprovante_tipo=row.comprovante.type;delete row.comprovante;}return row;});XLSX.utils.book_append_sheet(wb,XLSX.utils.json_to_sheet(data.length?data:[{Aviso:'Sem registros'}]),label);}XLSX.writeFile(wb,`CD-Controle-de-Diarias-${today}.xlsx`);toast('Planilha completa exportada.');}
  async function makeBackupPayload(){const data={};for(const [key,table] of Object.entries(tables))data[key]=await getAll(table);return {app:'CD - Controle de Diárias',formatVersion:3,createdAt:new Date().toISOString(),data};}
  function saveBlob(blob,name){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1500);}
  async function downloadJSONBackup(){try{const payload=await makeBackupPayload();saveBlob(new Blob([JSON.stringify(payload,null,2)],{type:'application/json'}),`CD-Backup-Completo-${today}.json`);toast('Backup completo baixado para o aparelho. Guarde também no Google Drive.');}catch(e){toast('Não foi possível gerar o backup: '+e.message);}}
  function normalizeExcelRows(rows){return rows.filter(r=>r&&Object.keys(r).some(k=>k!=='Aviso'&&r[k]!==''&&r[k]!=null)).map(r=>{const x={...r};delete x.empresa_nome;delete x.__rowNum__;return x;});}
  async function validateAndRestore(payload){if(payload?.app!=='CD - Controle de Diárias'||![1,2,3].includes(payload?.formatVersion)||!payload.data)throw new Error('Arquivo não reconhecido como backup do CD - Controle de Diárias.');for(const key of Object.keys(tables)){if(!Array.isArray(payload.data[key]))throw new Error('Backup incompleto: '+key+'.');}
    const prepared={};for(const [key,table] of Object.entries(tables)){prepared[table]=payload.data[key].map(row=>({...row,id:row.id||`restored-${Date.now()}-${Math.random().toString(16).slice(2)}`}));}
    await new Promise((resolve,reject)=>{const tx=localDB.transaction(Object.values(tables),'readwrite');for(const table of Object.values(tables)){const store=tx.objectStore(table);store.clear();prepared[table].forEach(row=>store.put(row));}tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error||new Error('Restauração cancelada'));});
    await loadAll();state.page='dashboard';render();toast('Restauração concluída! Seus dados foram recuperados.');}
  async function importBackupFile(file){try{if(!confirm('A restauração substituirá os cadastros atuais deste aparelho. Faça um backup antes. Deseja continuar?'))return;let payload;if(file.name.toLowerCase().endsWith('.json')){payload=JSON.parse(await file.text());}else{if(!window.XLSX)throw new Error('Biblioteca Excel indisponível. Conecte-se à internet e tente novamente.');const wb=XLSX.read(await file.arrayBuffer(),{type:'array',cellDates:false});const sheetMap={empresas:['Empresas'],diarias:['Diarias','Diárias'],notas:['Notas Fiscais'],recebiveis:['Recebimentos']};const data={};for(const [key,names] of Object.entries(sheetMap)){const name=names.find(n=>wb.SheetNames.includes(n));data[key]=name?normalizeExcelRows(XLSX.utils.sheet_to_json(wb.Sheets[name],{defval:null})):[];}payload={app:'CD - Controle de Diárias',formatVersion:2,data};}await validateAndRestore(payload);}catch(e){console.error(e);toast('Não foi possível restaurar: '+e.message);}}
  async function generateCustomReport(type){
    const companyId=$('#custom-report-company')?.value||'', period=$('#custom-report-period')?.value||'month', month=$('#custom-report-month')?.value||state.month;
    const opts={dates:$('#report-include-dates')?.checked,values:$('#report-include-values')?.checked,due:$('#report-include-due')?.checked,status:$('#report-include-status')?.checked,summary:$('#report-include-summary')?.checked};
    const [y,m]=month.split('-').map(Number),last=new Date(y,m,0).getDate(),start=period==='second'?16:1,end=period==='first'?15:period==='second'?last:last;
    const company=companyId?state.empresas.find(e=>e.id===companyId):null, list=state.diarias.filter(x=>(!companyId||x.empresa_id===companyId)&&String(x.data||'').startsWith(month)&&Number(String(x.data).slice(8,10))>=start&&Number(String(x.data).slice(8,10))<=end).sort((a,b)=>String(a.data).localeCompare(String(b.data)));
    const total=sum(list,'valor_total'),paid=sum(list.filter(x=>(x.status_pagamento||'Pendente')==='Pago'),'valor_total'),pending=Math.max(0,total-paid),label=period==='first'?'1ª quinzena (01–15)':period==='second'?`2ª quinzena (16–${last})`:'Mês completo';
    const columns=(opts.dates?'<th>Data</th>':'')+'<th>Empresa</th>'+(opts.values?'<th>Valor</th>':'')+(opts.due?'<th>Previsão</th>':'')+(opts.status?'<th>Situação</th>':'');
    const rows=list.map(x=>`<tr>${opts.dates?`<td>${dateBR(x.data)}</td>`:''}<td>${esc(companyName(x.empresa_id))}</td>${opts.values?`<td>${money(x.valor_total)}</td>`:''}${opts.due?`<td>${esc(paymentDueForDiary(x,state.empresas.find(e=>e.id===x.empresa_id))||'—')}</td>`:''}${opts.status?`<td>${esc(x.status_pagamento||'Pendente')}</td>`:''}</tr>`).join('');
    const art=document.createElement('div');art.className='report-art';art.innerHTML=`<div class=report-brand>CD <span>CONTROLE DE DIÁRIAS</span></div><h1>RELATÓRIO DE TRABALHO</h1><div class=report-sub>${esc(company?.nome_fantasia||company?.razao_social||'Todas as empresas')}<br>${label} • ${new Date(month+'-15T12:00:00').toLocaleDateString('pt-BR',{month:'long',year:'numeric'})}</div>${opts.summary?`<div class=report-summary><div><small>DIÁRIAS</small><b>${list.length}</b></div><div><small>VALOR TRABALHADO</small><b>${money(total)}</b></div>${opts.status?`<div><small>PAGO</small><b>${money(paid)}</b></div><div><small>PENDENTE</small><b>${money(pending)}</b></div>`:''}</div>`:''}<table class=report-data><thead><tr>${columns}</tr></thead><tbody>${rows||'<tr><td>Nenhuma diária encontrada nesse período.</td></tr>'}</tbody></table><div class=report-footer>Gerado em ${new Date().toLocaleString('pt-BR')}</div>`;
    const preview=$('#custom-report-preview');if(preview){preview.innerHTML='';preview.appendChild(art)}
    try{const canvas=await html2canvas(art,{backgroundColor:'#0b1220',scale:2});if(type==='jpg'){const a=document.createElement('a');a.download=`CD-Relatorio-${month}-${period}.jpg`;a.href=canvas.toDataURL('image/jpeg',.96);a.click()}else{const {jsPDF}=window.jspdf,pdf=new jsPDF('p','mm','a4'),w=190,h=canvas.height*w/canvas.width;pdf.addImage(canvas.toDataURL('image/png'),'PNG',10,10,w,h);pdf.save(`CD-Relatorio-${month}-${period}.pdf`)}}catch(e){toast('Falha ao gerar relatório: '+e.message)}
  }
  async function capture(type){const node=$('#page-content');try{const canvas=await html2canvas(node,{backgroundColor:'#020617',scale:2});if(type==='jpg'){const a=document.createElement('a');a.download=`CD-Balanco-${today}.jpg`;a.href=canvas.toDataURL('image/jpeg',.95);a.click();}else{const {jsPDF}=window.jspdf;const pdf=new jsPDF('p','mm','a4');const w=190,h=canvas.height*w/canvas.width;let y=8;let remaining=h;while(remaining>0){pdf.addImage(canvas.toDataURL('image/png'),'PNG',10,y,w,h);remaining-=277;if(remaining>0){pdf.addPage();y-=277;}}pdf.save(`CD-Balanco-${today}.pdf`);} }catch(e){toast('Falha na exportação: '+e.message);}}
  $('#navigation').addEventListener('click',e=>{const b=e.target.closest('[data-page]');if(!b)return;state.page=b.dataset.page;document.querySelectorAll('.nav-link').forEach(x=>x.classList.toggle('active',x===b));$('#sidebar').classList.remove('open');render();});
  $('#menu-toggle').onclick=()=>$('#sidebar').classList.toggle('open');
  $('#quick-diary').onclick=()=>openForm('diaria');
  $('#modal-root').addEventListener('change',e=>{if(e.target.name==='cnpj'&&e.target.value.replace(/\D/g,'').length===14)lookupCNPJ(e.target.value);});
  $('#modal-root').addEventListener('keydown',e=>{if(e.target.name==='cnpj'&&e.key==='Enter'){e.preventDefault();lookupCNPJ(e.target.value);}});
  loadAll();render();
})();